G={}
R=[
dict(t="Soupe de légumes-racines rôtis",d="Faire rôtir les légumes dans cette recette permet de maximiser la saveur de la soupe. De plus, tous ces légumes sont abondants et disponibles pendant les mois d'hiver.",p="8",s="1 1/2 tasse",
i=["1 pulvérisation, 0.25 g d'huile de cuisson antiadhésive en spray","1 petite courge butternut (environ 1 livre) (pelée, épépinée et coupée en morceaux de 1 pouce)","2 petits navets (pelés et coupés en morceaux de 1 pouce)","2 panais moyens (pelés et coupés en morceaux de 1 pouce)","2 carottes moyennes (pelées et coupées en morceaux de 1 pouce)","1 gros oignon (pelé et coupé en dés)","3 branches de céleri (en dés)","1/2 chou vert pommé (haché)","4 gousses d'ail (hachées)","1 c. à soupe d'huile d'olive","1 c. à soupe d'herbes de Provence","2 quarts de bouillon de légumes à faible teneur en sodium","1 c. à soupe de vinaigre de xérès","1 c. à café de sel","1/2 c. à café de poivre noir"],
st=["Préchauffez le four à 400 degrés F. Enduisez une grande plaque de cuisson (ou deux de taille moyenne) d'huile en spray. Réservez.","Dans un grand bol, mélangez tous les légumes, y compris l'ail, avec l'huile d'olive et les herbes de Provence. Versez sur la ou les plaques préparées et faites rôtir 45 minutes, jusqu'à ce qu'ils soient bien cuits et commencent à dorer.","Une fois les légumes rôtis, versez-les dans une grande marmite à soupe. Mélangez avec le bouillon de légumes et portez à ébullition. Réduisez le feu et laissez mijoter 10 minutes.","Mixez la soupe avec un mixeur plongeant ou par portions dans un blender.","Assaisonnez la soupe avec le vinaigre de xérès, le sel et le poivre."]),
dict(t="Tofu brouillé aux courgettes et aux tomates cerises",d="Voici une recette végétarienne, végétalienne, pauvre en glucides et très pauvre en glucides, qui présente un tofu brouillé coloré, un petit-déjeuner copieux d'origine végétale riche en protéines et en fibres grâce au tofu extra ferme et aux légumes frais. Le curcuma apporte une saveur chaude et terreuse et une teinte dorée sans avoir besoin d'œufs. C'est un choix nourrissant et attentif aux glucides qui favorise des taux stables de glucose sanguin (glycémie) chez les personnes diabétiques.",p="4",s="2 tasses",
i=["2 c. à soupe d'huile d'olive","1 oignon jaune moyen (en dés)","2 courgettes moyennes (coupées en demi-lunes)","3 gousses d'ail (hachées)","1 c. à café de curcuma","1 c. à café de sel","1/2 c. à café de basilic","1/2 c. à café d'origan frais","12 onces de tofu extra ferme","1 tasse de tomates cerises (coupées en deux)"],
st=["Faites chauffer une grande poêle à feu moyen et ajoutez l'huile d'olive.","Ajoutez l'oignon, les courgettes, l'ail et les épices dans la poêle. Émiettez le tofu avec vos doigts dans la poêle et remuez pour mélanger. Faites sauter jusqu'à ce que les légumes soient tendres, 5 à 7 minutes.","Retirez du feu et incorporez les tomates cerises."]),
dict(t="Chou sauté et sa vinaigrette au vinaigre de cidre",d="Du chou sauté nappé d'une vinaigrette au vinaigre de cidre, où le croquant délicat du chou rencontre l'attrait acidulé d'une vinaigrette savoureuse. Ce plat adapté aux personnes diabétiques est assez facile pour un repas en semaine.",p="6",s="1 tasse",
i=["2 c. à soupe d'huile d'olive","1 petit chou rouge (finement émincé)","2 c. à soupe de vinaigre de cidre de pomme","1 c. à soupe de moutarde de Dijon","1 c. à soupe de sirop d'érable","1/2 c. à café de graines de carvi","1/2 c. à café de sel","1/4 c. à café de poivre noir"],
st=["Dans une grande poêle, faites chauffer l'huile d'olive à feu moyen.","Ajoutez le chou finement émincé dans la poêle en le remuant pour l'enrober d'huile.","Faites sauter le chou 10 à 12 minutes, jusqu'à ce qu'il soit tendre mais encore un peu croquant.","Dans un petit bol, fouettez ensemble le vinaigre de cidre de pomme, la moutarde de Dijon, le sirop d'érable et les graines de carvi.","Versez la vinaigrette au vinaigre de cidre sur le chou sauté. Mélangez pour enrober uniformément.","Assaisonnez de sel et de poivre noir.","Continuez à faire sauter encore 2 à 3 minutes pour permettre aux saveurs de se mêler."]),
dict(t="Mini-sandwichs à la salade de poulet",d="Cette version allégée de la salade de poulet utilise du yaourt grec acidulé et de la mayonnaise légère avec d'autres ingrédients sains et savoureux ! Pour un repas plus pauvre en glucides, servez cette salade de poulet sur des feuilles de laitue au lieu de mini-pains.",p="6",s="1 mini-sandwich",
i=["2 tasses de poulet cuit (haché)","1 branche de céleri (finement coupée en dés)","2 c. à soupe d'oignon rouge (coupé en petits dés)","1/3 tasse de canneberges séchées","2 c. à soupe d'amandes effilées (non salées)","1/4 tasse de yaourt grec nature sans matières grasses","1/4 tasse de mayonnaise légère","1 c. à café de moutarde de Dijon","1 c. à soupe de jus de citron (d'environ 1/2 citron moyen)","poivre noir fraîchement moulu, selon le goût","6 mini-pains à sandwich de blé complet","1 tomate moyenne (coupée en 6 tranches)"],
st=["Mélangez tous les ingrédients, sauf les pains et la tomate, dans un bol à mélanger moyen.","Servez 1/3 tasse de salade de poulet sur chaque mini-pain, garnie d'1 tranche de tomate."]),
dict(t="Dip à l'avocat et au concombre",d="Cette entrée légère et savoureuse est un excellent plat d'ouverture pour une soirée romantique. Vous pouvez aussi la savourer comme en-cas n'importe quel autre jour. Des rondelles de concombre ou des endives font aussi d'excellents accompagnements pour tremper !",p="2",s="1/4 tasse de dip + 1 tranche de pain",
i=["1/2 petit avocat","1 concombre à cornichons entier (comme le Kirby) ou 1/3 de petit concombre","2 c. à soupe de crème aigre (sans matières grasses)","1 c. à café de menthe fraîche hachée ou 1/4 c. à café de menthe séchée (émiettée)","1 c. à café de jus de citron vert","1/8 c. à café de sel","1/8 c. à café de graines de céleri","1/8 c. à café de poivre noir","2 tranches de pain de blé complet (sandwich thins)"],
st=["Dans un bol moyen, écrasez l'avocat à la fourchette jusqu'à la consistance souhaitée (légèrement grossière ou lisse).","Hachez finement le concombre à cornichons ou épluchez, épépinez et hachez finement le concombre ordinaire. (Vous devriez obtenir environ 1/3 tasse.) Incorporez le concombre et les ingrédients restants à l'avocat. Étalez sur le sandwich thin pour servir immédiatement, ou couvrez et réfrigérez jusqu'à 8 heures.","Astuce du cuisinier : pour conserver l'avocat restant, saupoudrez la surface exposée de jus de citron frais, de jus de citron vert ou de vinaigre blanc. Couvrez-le bien de film plastique ou placez-le dans un contenant hermétique et réfrigérez. Il devrait se conserver 1 à 2 jours."]),
dict(t="Houmous aux haricots noirs",d="Pourquoi s'arrêter aux pois chiches ? Remplacez-les par des haricots noirs et ajoutez un peu de cumin pour une version nouvelle et relevée du houmous. Servez avec des bâtonnets de légumes frais à tremper.",p="8",s="2 c. à soupe de houmous + 1/4 concombre moyen + 1/4 carotte moyenne",
i=["1 c. à soupe d'huile d'olive","1/8 c. à café de poivre noir","1 c. à soupe de tahini","1/2 c. à café de cumin","1 boîte (15 onces) de haricots noirs (à faible teneur en sodium, rincés et égouttés)","1/4 c. à café d'ail en poudre","2 c. à soupe d'eau","2 concombres moyens (coupés en bâtonnets)","2 carottes moyennes (coupées en bâtonnets)"],
st=["Placez tous les ingrédients dans un robot culinaire et mixez jusqu'à obtenir une texture lisse. Ajoutez de l'eau si la consistance est trop épaisse.","Servez avec des bâtonnets de carotte et de concombre."]),
dict(t="Œufs mimosa à la moutarde de Dijon et au raifort",d="Les œufs mimosa sont un excellent en-cas ou une excellente entrée pauvre en glucides. Et ils sont parfaits à Pâques si vous avez beaucoup d'œufs teints en reste ! Cette version traditionnelle comporte de la moutarde de Dijon relevée et du raifort pour plus de saveur sans beaucoup de sel ajouté. Nous avons remplacé la majeure partie de la mayonnaise par du yaourt nature pour une garniture plus légère.",p="6",s="2 moitiés",
i=["6 gros œufs","1 c. à soupe de vinaigre blanc","6 c. à soupe de yaourt nature (sans matières grasses)","1 c. à soupe de mayonnaise légère","1 c. à soupe de ciboulette fraîche (hachée)","2 c. à café de moutarde de Dijon","1/2 c. à café de raifort","1/4 c. à café de curcuma","1/8 c. à café de paprika"],
st=["Pour préparer les œufs : placez les œufs dans une casserole assez grande pour qu'ils ne soient pas serrés. Ajoutez de l'eau pour couvrir les œufs d'environ 1 pouce. Couvrez la casserole et portez à ébullition. Dès que l'eau bout, après environ 6 à 7 minutes, retirez la casserole du feu et posez-la sur un brûleur inutilisé. Ajoutez le vinaigre à l'eau (pour faciliter l'écalage des œufs). Laissez les œufs reposer dans l'eau chaude 20 à 30 minutes.","Préparez un grand bol d'eau glacée. À l'aide d'une écumoire, transférez les œufs dans le bain d'eau glacée et laissez-les refroidir 15 à 20 minutes. Retirez délicatement chaque œuf de l'eau glacée et tapotez doucement sa coquille jusqu'à ce qu'elle soit fissurée de partout (mais ne l'écalez pas). Remettez les œufs fissurés dans le bain d'eau glacée (préparez un nouveau bain de glace si nécessaire) pendant 10 minutes. Retirez les œufs de l'eau glacée et roulez-les doucement entre vos paumes. Les coquilles devraient se détacher facilement. Jetez les coquilles.","Coupez chaque œuf en deux et retirez les jaunes. Jetez un jaune et mettez les cinq autres dans un bol. Placez les blancs d'œufs sur un plat, face coupée vers le haut.","Écrasez les jaunes avec le yaourt, la mayonnaise, la ciboulette, la moutarde, le raifort, le curcuma, le sel et le poivre. Remplissez les blancs d'œufs de la préparation aux jaunes à la cuillère ou à la poche à douille. Saupoudrez légèrement de paprika."]),
dict(t="Frittata aux asperges",d="Elle peut faire un excellent petit-déjeuner, brunch ou dîner rapide, riche en protéines et en légumes. Si vous n'aimez pas les asperges, vous pouvez les remplacer par des courgettes ou du brocoli.",p="6",s="1 part",
i=["1 pulvérisation, 0.25 g d'huile de cuisson antiadhésive en spray","1 botte (environ 12 onces) d'asperges fines (parées)","1 c. à soupe d'huile d'olive","2 tasses de substitut d'œuf","2 c. à soupe de lait écrémé","1/2 c. à café de sel","1/4 c. à café de poivre noir fraîchement moulu","1/8 c. à café de flocons de piment rouge concassés (facultatif)","1 c. à café de margarine (sans gras trans)","1/4 tasse de mozzarella râpée allégée en matières grasses (allégée, râpée)","1/4 tasse de parmesan râpé"],
st=["Préchauffez le four à 425 degrés F.","Vaporisez une plaque de cuisson d'huile en spray. Dans un petit bol, mélangez les asperges avec l'huile d'olive. Placez-les sur la plaque de cuisson et faites cuire au four environ 12 minutes. Coupez les asperges cuites en morceaux de 1/2 pouce. Réservez.","Dans un bol moyen, fouettez ensemble le substitut d'œuf, le lait, le sel, le poivre et les flocons de piment rouge. Réservez et préparez le gril du four.","Vaporisez d'huile en spray une poêle antiadhésive allant au four de 9 1/2 pouces de diamètre. Ajoutez la margarine dans la poêle et faites-la fondre à feu moyen. Ajoutez les asperges dans la poêle et versez le mélange d'œufs sur les asperges. Faites cuire quelques minutes jusqu'à ce que les œufs commencent à prendre.","Ajoutez la mozzarella et le parmesan. Réduisez le feu à moyen-doux et faites cuire jusqu'à ce que la frittata soit presque prise mais que le dessus soit encore coulant, environ 2 minutes.","Placez la poêle sous le gril. Faites gratiner jusqu'à ce que le dessus soit pris et doré, environ 2 à 4 minutes. Laissez reposer la frittata 2 minutes. À l'aide d'une spatule en caoutchouc, décollez la frittata de la poêle et faites-la glisser sur une assiette. Coupez la frittata en 6 parts égales et servez."]),
dict(t="Soupe de haricots blancs et de légumes à l'épeautre",d="Cette soupe copieuse et riche en légumes réchauffera même la journée la plus froide ! Utilisez du bouillon de légumes à faible teneur en sodium pour en faire une option végétarienne.",p="9",s="1 tasse",
i=["1 c. à soupe d'huile d'olive","1 oignon moyen (en dés)","2 gousses d'ail (hachées)","1 c. à café d'assaisonnement italien","1/2 c. à café de paprika fumé","1/8 c. à café de piment de Cayenne","2 carottes moyennes (pelées et tranchées)","2 courges jaunes moyennes (non pelées et coupées en dés)","4 tasses de bouillon de poulet à faible teneur en sodium","1 boîte (15 onces) de tomates en dés en conserve","1 boîte (15 onces) de pois chiches (égouttés)","2 c. à soupe de jus de citron","1/2 c. à café de sel","1/4 c. à café de poivre noir","2 tasses d'épeautre cuit (aliments secs emballés)"],
st=["Dans une grande casserole, faites chauffer l'huile à feu moyen. Ajoutez l'oignon et faites-le sauter 5 minutes. Ajoutez l'ail, l'assaisonnement italien, le paprika fumé et le piment de Cayenne et faites sauter 2 minutes.","Ajoutez les carottes et la courge jaune et faites sauter 3 minutes. Versez le bouillon et les tomates et portez à ébullition. Réduisez le feu et laissez mijoter 30 minutes.","Ajoutez les haricots et laissez mijoter 5 minutes. Versez le jus de citron en filet. Assaisonnez de sel et de poivre.","Pour servir, placez un peu moins de 1/4 tasse d'épeautre cuit au fond de chaque bol à soupe. Versez la soupe à la louche sur l'épeautre. Si désiré, saupoudrez de persil frais."]),
dict(t="Lasagnes de courgettes sans pâtes",d="L'auteure Robyn Webb explique : « Les lasagnes de courgettes ont été les toutes premières lasagnes que j'ai préparées. À l'origine, je les faisais avec des pâtes, mais je me rends compte aujourd'hui que de longues lanières de courgette remplacent à merveille les pâtes. »",p="18",s="1 rectangle de 2 × 3 pouces",
i=["2 c. à soupe d'huile d'olive","6 gousses d'ail (hachées, utilisation divisée)","1 boîte (28 onces) de tomates en conserve (de préférence dans leur propre jus, égouttées, liquide réservé)","5 feuilles de basilic frais (tranchées ou entières)","1/2 c. à café de sel casher (utilisation divisée)","1/2 c. à café de poivre noir (fraîchement moulu, utilisation divisée)","1/4 c. à café de flocons de piment rouge moulus (facultatif)","3 grosses courgettes","16 onces de tofu ferme","1/2 tasse de persil frais (haché)","1 c. à soupe de jus d'1/2 citron","2 c. à café de zeste de citron","1 tasse de fromage ricotta (allégé)","1 tasse de mozzarella (râpée, partiellement écrémée)","1 gros œuf (battu)","1/4 tasse de parmesan ou de pecorino romano (râpé)"],
st=["Tapissez deux plaques de cuisson de papier sulfurisé et réservez.","Faites chauffer l'huile d'olive et 5 gousses d'ail hachées dans une grande poêle avec couvercle à feu doux (n'utilisez pas de casserole profonde, car vous voulez que l'eau s'évapore rapidement et que la sauce épaississe). Faites cuire l'ail environ 6 à 7 minutes en remuant de temps en temps.","Pendant ce temps, mettez les tomates égouttées dans un bol profond. Écrasez les tomates avec vos mains jusqu'à obtenir une texture grossière. Ajoutez les tomates et le basilic dans la poêle et laissez mijoter sans couvercle 20 à 25 minutes, jusqu'à ce que la sauce épaississe. Ajoutez un peu du liquide réservé de la boîte de tomates si la sauce est trop épaisse.","Préchauffez le four à 400 °F. Pendant que la sauce mijote, coupez les courgettes dans le sens de la longueur en tranches de 1/8 pouce d'épaisseur avec un couteau ou une mandoline. Disposez les courgettes sur la plaque de cuisson préparée. Saupoudrez légèrement les courgettes de sel. Faites cuire les courgettes environ 10 à 12 minutes, jusqu'à ce qu'elles soient légèrement dorées. Sortez les courgettes du four. Roulez délicatement les tranches de courgette dans un torchon pour éliminer l'excès d'humidité, ou utilisez simplement du papier absorbant et épongez très bien. Veillez à garder les tranches intactes. Ajoutez 1/4 c. à café de sel, 1/4 c. à café de poivre et les flocons de piment rouge concassés (le cas échéant) à la sauce tomate.","Dans un robot culinaire ou un blender, mixez le tofu, le persil, le jus de citron, le zeste de citron et la gousse d'ail restante jusqu'à obtenir une texture lisse. Versez dans un grand bol et incorporez la ricotta, la mozzarella, l'œuf, 1/4 c. à café de sel et le poivre.","Versez environ 1/3 tasse de sauce marinara au fond d'un plat de cuisson de 9 × 12. Ajoutez une couche de tranches de courgette en les faisant se chevaucher légèrement. Ajoutez 1/3 de la préparation à la ricotta sur les courgettes, en l'étalant uniformément avec une spatule. Ajoutez environ 1/3 du reste de sauce marinara sur la garniture de tofu et de fromage. Répétez le montage des couches jusqu'à épuisement des ingrédients, en terminant par la sauce marinara. Saupoudrez le dessus des lasagnes de parmesan ou de pecorino romano.","Couvrez sans serrer de papier d'aluminium et faites cuire 35 minutes. Retirez le couvercle et faites cuire encore 15 minutes. Sortez les lasagnes du four et laissez reposer à température ambiante 10 à 15 minutes pour qu'elles se tassent et soient plus faciles à couper. Coupez en carrés."]),
dict(t="Quiche sans pâte aux épinards et aux champignons",d="Cette recette de petit-déjeuner pauvre en glucides est conçue pour deux personnes. Parfaite pour un petit-déjeuner copieux, mais elle convient aussi pour le déjeuner ou le dîner.",p="2",s="1 quiche",
i=["1 c. à café d'huile de canola","6 onces de champignons portobello (équeutés et tranchés)","3 branches d'oignon vert (ciboule) (hachées)","2 gousses d'ail (hachées)","1 tasse d'épinards surgelés (décongelés et pressés)","1 c. à café de fécule de maïs","3/4 tasse de lait écrémé","1/2 tasse de substitut d'œuf","2 c. à soupe de mozzarella partiellement écrémée (râpée)","1 c. à soupe de parmesan (râpé)","1/8 c. à soupe de poivre noir","1 c. à café de noix de muscade moulue"],
st=["Préchauffez le four à 350 degrés F. Vaporisez légèrement d'huile en spray deux ramequins allant au four de 10 onces ou des moules à tarte individuels. Placez-les sur une plaque de cuisson peu profonde.","Dans une grande poêle antiadhésive, faites chauffer l'huile à feu moyen en la faisant tourner pour enduire le fond. Faites cuire les champignons et les oignons verts 2 minutes en remuant de temps en temps.","Réduisez le feu à moyen-doux et faites cuire 3 à 4 minutes, jusqu'à ce que tout le liquide soit absorbé. Incorporez l'ail et faites cuire de 30 secondes à 1 minute, jusqu'à ce qu'il dégage son parfum.","Retirez du feu. Ajoutez les épinards. À l'aide d'une cuillère, séparez-les en petits morceaux.","Mettez la fécule de maïs dans un bol moyen. Versez lentement le lait en fouettant pour la dissoudre. Incorporez en fouettant les ingrédients restants et ajoutez le mélange de champignons. Répartissez entre les ramequins.","Faites cuire 30 minutes, jusqu'à ce que le centre soit gonflé et pris (il ne doit plus trembler lorsqu'on secoue doucement). Laissez reposer 5 minutes avant de servir."]),
dict(t="Brochettes de fruits et de fromage",d="Ces jolies brochettes sont un excellent en-cas pour les enfants comme pour les adultes. Les fruits et le fromage forment une savoureuse combinaison de glucides et de protéines, et vous laisseront rassasié.",p="4",s="1 brochette",
i=["2 kiwis moyens (pelés et tranchés)","8 fraises moyennes (équeutées et coupées en deux)","16 grains de raisin entiers","3 bâtonnets de fromage en fils allégé entiers (chacun coupé en 4 morceaux)","4 brochettes en bois entières"],
st=["Pour préparer les brochettes, alternez fraises, raisins, tranches de kiwi et fromage sur une brochette (4 moitiés de fraise, 4 grains de raisin, 2 à 3 tranches de kiwi et 3 morceaux de fromage par brochette).","Répétez l'opération pour les 3 autres brochettes."]),
dict(t="Poulet à l'ail façon scampi avec roquette",d="Savourez cette variante du classique scampi aux crevettes pour le dîner une fois (ou plusieurs fois) ce mois-ci. C'est un plat simple en une seule casserole qui comprend une source de protéines maigres, des céréales complètes et une portion de légumes.",p="4",s="3 onces de poulet + 1 ½ tasse de pâtes et de légumes",
i=["14 onces de blancs de poulet (sans os, sans peau, coupés en grands morceaux fins de la taille d'une bouchée)","2 c. à soupe d'huile d'olive extra vierge","4 gousses d'ail (hachées)","1 c. à soupe de parties blanches + 1/3 tasse de parties vertes d'oignon vert (ciboule) (finement tranchées, utilisation divisée)","1/4 tasse de jus de citron","8 onces de linguine de blé complet secs","1 c. à café de beurre non salé","4 tasses de roquette (déchirée en gros morceaux)","3/4 c. à café de sel casher","1/2 c. à café de poivre noir (selon le goût)"],
st=["Préchauffez le four à 400 degrés F. Placez les morceaux de poulet, l'huile, l'ail, les parties blanches de l'oignon vert et le jus de citron dans un plat de cuisson à bords hauts de 9x13 pouces. Remuez pour enrober, puis faites cuire 12 minutes, jusqu'à ce que le poulet soit bien cuit.","Pendant ce temps, faites cuire les linguine selon les instructions de l'emballage, sans ajouter d'huile ni de sel. Égouttez les linguine, remettez-les dans la casserole et mélangez-les avec le beurre.","Incorporez la roquette et les parties vertes de l'oignon vert au poulet, puis mélangez le poulet avec les linguine. Saupoudrez de sel et de poivre. Servez chaud sur un grand plat."]),
dict(t="Poulet mariné grillé aux courgettes",d="Ce délicieux plat est parfait pour un dîner de semaine chargé. N'oubliez pas de faire mariner le poulet la veille si vous voulez plus de saveur.",p="4",s="4 onces de filets de poulet + 1/2 tasse de rondelles de courgette",
i=["1/2 tasse de jus de 2 clémentines","3 c. à soupe d'huile d'olive (utilisation divisée)","1 gousse d'ail (hachée)","1/8 c. à café de poivre noir","1 pulvérisation, 0.25 g d'huile de cuisson antiadhésive en spray","1 livre de filets de poulet (sans os)","2 courgettes moyennes (coupées en rondelles de 1/2 pouce)"],
st=["Dans un bol moyen, fouettez ensemble le jus de clémentine, 1 c. à soupe d'huile d'olive, l'ail et le poivre noir. Placez les filets de poulet dans un grand sac de conservation en plastique. Versez la marinade sur les filets et enrobez bien. Fermez le sac et réfrigérez 1 heure ou toute la nuit.","Vaporisez le gril d'huile en spray et préchauffez à feu moyen-vif. Placez les filets de poulet sur le gril et badigeonnez-les de la marinade restante. Faites griller environ 4 à 5 minutes de chaque côté, jusqu'à ce qu'ils soient cuits.","Badigeonnez les courgettes de 2 c. à soupe d'huile d'olive. Faites griller 3 à 5 minutes de chaque côté. Servez les filets de poulet avec les rondelles de courgette."]),
dict(t="Salade hachée au miso",d="Le croquant du chou, des carottes et de l'oignon s'associe à une vinaigrette aux saveurs asiatiques adaptée aux personnes diabétiques, qui irait très bien avec un dîner sauté au wok !",p="0",s="1/2 tasse",
i=["2 c. à soupe de sauce soja à teneur réduite en sodium","1 c. à soupe de pâte de miso","2 c. à soupe de vinaigre de vin de riz","2 c. à café d'huile de sésame grillé","2 c. à soupe d'huile d'olive","1 c. à soupe de sirop polyvalent non sucré","1 c. à soupe de gingembre frais (haché)","1 c. à soupe de jus de citron vert","1 petit chou rouge (coupé très finement)","1/2 oignon rouge moyen (coupé très finement)","1/2 tasse de maïs","1 grosse carotte (pelée en rubans)","2 branches de ciboule (hachées, parties blanches et vert clair)","2 c. à soupe de coriandre fraîche (hachée)"],
st=["Dans un grand bol, fouettez la sauce soja, la pâte de miso blanc de riz, le vinaigre de vin de riz, l'huile de sésame grillé, l'huile d'olive, le sirop polyvalent non sucré, le gingembre frais et le jus de citron vert.","Ajoutez le chou, l'oignon rouge, le maïs, la carotte, la ciboule et la coriandre et mélangez pour combiner.","Laissez reposer au moins 15 minutes avant de servir afin que les saveurs se mêlent."]),
]
